import * as React from "react";

export type StopSquareIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function StopSquareIcon({ size = 20, ...props }: StopSquareIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <rect x="4" y="4" width="16" height="16" rx="2" /><path d="M9.5 9.5h5v5h-5Z" />
    </svg>
  );
}
